INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q714601', 'Predynastic Period of Egypt', 'Prehistoric Egypt and Predynastic Egypt was the period of time starting at the first human occupation of the region and ending at the First Dynasty of Egypt around 3100 BC. At the end of prehistory, "Predynastic Egypt" is traditionally defined as the period from the final part of the Neolithic period beginning c. 6210 BC to the end of the Naqada III period c. 3000 BC. The dates of the Predynastic period were first defined before widespread archaeological excavation of Egypt took place, and recent finds indicating a gradual Predynastic development have led to controversy over when exactly…', -6500, NULL, NULL, -3100, NULL, NULL, 'century', '65th century BCE – 3100 BCE', 69, 'https://en.wikipedia.org/wiki/Predynastic_Egypt'),
  ('Q187979', 'Early Dynastic Period of Egypt', 'The Early Dynastic Period, also known as Archaic Period or the Thinite Period (from Thinis, the hometown of its rulers), is the era of ancient Egypt that immediately follows the unification of Upper and Lower Egypt in c. 3150 BC. It is generally taken to include the First Dynasty and the Second Dynasty, lasting from the end of the archaeological culture of Naqada III until c. 2686 BC, or the beginning of the Old Kingdom. With the First Dynasty, the Egyptian capital moved from Thinis to Memphis, with the unified land being ruled by an Egyptian god-king.', -3100, NULL, NULL, -2686, NULL, NULL, 'year', '3100 BCE – 2686 BCE', 78, 'https://en.wikipedia.org/wiki/Early_Dynastic_Period_of_Egypt'),
  ('Q1036947', 'Battle of the Delta', 'The Battle of the Delta was a sea battle between Egypt and the Sea Peoples, circa 1175 BC, when the Egyptian pharaoh Ramesses III repelled a major sea invasion. The conflict occurred on the shores of the eastern Nile Delta and on the border of the Egyptian Empire in Syria, although precise locations of the battles are unknown.', -1178, NULL, NULL, NULL, NULL, NULL, 'year', '1178 BCE', 57, 'https://en.wikipedia.org/wiki/Battle_of_the_Delta'),
  ('Q544239', 'Battle of Pelusium', 'The Battle of Pelusium was the first major battle between the Achaemenid Empire and Egypt. This decisive battle transferred the throne of the Pharaohs to Cambyses II of Persia, marking the beginning of the Achaemenid Twenty-seventh Dynasty of Egypt.', -525, 5, NULL, NULL, NULL, NULL, 'month', 'May 525 BCE', 61, 'https://en.wikipedia.org/wiki/Battle_of_Pelusium'),
  ('Q20987758', 'Battle of Pelusium', 'The Battle of Pelusium (373 BC) or the Battle of Mendes took place after the Persian king Artaxerxes II launched an attack on Egypt with the aim of restoring Egypt to Persian rule. The campaign failed, and ended with the defeat of the Persians and their Greek mercenaries.', -343, NULL, NULL, NULL, NULL, NULL, 'year', '343 BCE', 47, 'https://en.wikipedia.org/wiki/Battle_of_Pelusium_(373_BC)'),
  ('Q630781', 'Battle of Raphia', 'The Battle of Raphia was fought on 22 June 217 BC near modern Rafah between the forces of Ptolemy IV Philopator, king and pharaoh of Ptolemaic Egypt and Antiochus III the Great of the Seleucid Empire during the Syrian Wars. It was one of the largest battles of the Hellenistic kingdoms and of the ancient world, and determined the sovereignty of Coele-Syria.', -217, 6, 22, NULL, NULL, NULL, 'day', '22 June 217 BCE', 64, 'https://en.wikipedia.org/wiki/Battle_of_Raphia'),
  ('Q1975400', 'Battle of the Nile', 'The Battle of the Nile in early 47 BC saw the combined Roman–Egyptian armies of Julius Caesar and Cleopatra VII defeat those of the rival Queen Arsinoe IV and King Ptolemy XIII and secure the throne of Egypt.', -47, NULL, NULL, NULL, NULL, NULL, 'year', '47 BCE', 53, 'https://en.wikipedia.org/wiki/Battle_of_the_Nile_(47_BC)'),
  ('Q16208146', 'Siege of Alexandria', 'The siege of Alexandria was a series of skirmishes and battles occurring between the forces of Julius Caesar, Cleopatra VII, Arsinoe IV, and Ptolemy XIII, between 48 and 47 BC. During this time Caesar was engaged in a civil war against remaining Republican forces. The siege was lifted by relief forces arriving from Syria.', -47, NULL, NULL, NULL, NULL, NULL, 'year', '47 BCE', 53, 'https://en.wikipedia.org/wiki/Siege_of_Alexandria_(47_BC)'),
  ('Q2116320', 'Final War of the Roman Republic', 'The War of Actium or Actian War (32–30 BC) was the last civil war of the Roman Republic, fought between Mark Antony (assisted by Cleopatra and by extension Ptolemaic Egypt) and Octavian. In 32 BC, Octavian convinced the Roman Senate to declare war on the Egyptian queen Cleopatra.', -32, NULL, NULL, -30, NULL, NULL, 'year', '32 BCE – 30 BCE', 63, 'https://en.wikipedia.org/wiki/War_of_Actium'),
  ('Q2237576', 'Battle of Heliopolis', 'The Battle of Heliopolis or Ayn Shams was a decisive battle in 640 between Arab Muslim armies and Byzantine Empire forces for the control of Egypt. Though there were several major skirmishes after this battle, it effectively decided the fate of the Byzantine rule in Egypt, and opened the door for the Muslim conquest of the Roman Exarchate of Africa.', 640, 7, 6, NULL, NULL, NULL, 'day', '6 July 640', 56, 'https://en.wikipedia.org/wiki/Battle_of_Heliopolis'),
  ('Q815105', 'Siege of Alexandria', 'Forces of the Rashidun Caliphate seized the major Mediterranean port of Alexandria from the Eastern Roman Empire in the middle of the 7th century AD. Alexandria had been the capital of the Byzantine province of Egypt. This ended Eastern Roman maritime control and economic dominance of the Eastern Mediterranean and thus continued to shift geopolitical power further in favor of the Rashidun Caliphate.', 641, 3, NULL, 641, 9, NULL, 'month', 'March 641 – September 641', 47, 'https://en.wikipedia.org/wiki/Siege_of_Alexandria_(641)'),
  ('Q677982', 'Siege of Ascalon', 'The siege of Ascalon took place from 25 January to 22 August 1153, in the time period between the Second and Third Crusades, and resulted in the capture of the Fatimid Egyptian fortress by the Kingdom of Jerusalem. Ascalon was an important castle that was used by the Fatimids to launch raids into the Crusader kingdom''s territory, and by 1153 it was the last coastal city in Palestine that was not controlled by the Crusaders.', 1153, NULL, NULL, 1153, 8, 22, 'year', '1153', 58, 'https://en.wikipedia.org/wiki/Siege_of_Ascalon'),
  ('Q4872816', 'Battle of al-Babein', 'The Battle of al-Babein took place on March 18, 1167, during the third Crusader invasion of Egypt. King Amalric I of Jerusalem, and a Zengid army under Shirkuh, both hoped to take the control of Egypt over from the Fatimid Caliphate.', 1167, 3, 18, NULL, NULL, NULL, 'day', '18 March 1167', 47, 'https://en.wikipedia.org/wiki/Battle_of_al-Babein'),
  ('Q742693', 'Siege of Damietta', 'The siege of Damietta of 1218–1219 was part of the Fifth Crusade in which the Crusaders attacked the Egyptian port city of Damietta. The city was besieged in 1218 and taken by the Crusaders in 1219.', 1218, 5, NULL, 1219, 11, 5, 'month', 'May 1218 – 5 November 1219', 61, 'https://en.wikipedia.org/wiki/Siege_of_Damietta_(1218%E2%80%931219)'),
  ('Q1876031', 'Siege of Damietta', 'The siege of Damietta occurred in 1249 and was part of the Seventh Crusade. Louis IX of France landed at Damietta in 1249.', 1249, 6, 5, 1249, 6, 6, 'day', '5 June 1249 – 6 June 1249', 52, 'https://en.wikipedia.org/wiki/Siege_of_Damietta_(1249)'),
  ('Q1148862', 'Battle of Fariskur', 'The Battle of Fariskur was the last major battle of the Seventh Crusade. The battle was fought on 6 April 1250, between the Crusaders led by King Louis IX of France (later Saint Louis) and Egyptian forces led by Turanshah of the Ayyubid dynasty.', 1250, 4, 6, NULL, NULL, NULL, 'day', '6 April 1250', 60, 'https://en.wikipedia.org/wiki/Battle_of_Fariskur_(1250)'),
  ('Q2528398', 'Battle of Mansurah', 'The Battle of Mansurah was fought from 8 to 11 February 1250, between crusaders led by King Louis IX of France and Ayyubid forces led by Vizier Fakhr al-Din ibn al-Shaykh, Qutuz and Baybars . It was fought in present-day Mansoura, Egypt.', 1250, 2, 8, 1250, 2, 11, 'day', '8 February 1250 – 11 February 1250', 57, 'https://en.wikipedia.org/wiki/Battle_of_Mansurah_(1250)'),
  ('Q4338038', 'Ottoman–Mamluk War of 1516–17', 'The Ottoman–Mamluk War of 1516–1517 was the second major conflict between the Egypt-based Mamluk Sultanate and the Ottoman Empire, which led to the Fall of the Mamluk Sultanate and the incorporation of the Levant, Egypt, and the Hejaz as provinces of the Ottoman Empire. The war transformed the Ottoman Empire from a realm at the margins of the Islamic world, mainly located in Anatolia and the Balkans, to a huge empire encompassing much of the traditional lands of Islam, including the cities of Mecca, Cairo, Damascus, and Aleppo.', 1516, NULL, NULL, 1517, 1, 22, 'year', '1516 – 22 January 1517', 63, 'https://en.wikipedia.org/wiki/Ottoman%E2%80%93Mamluk_War_(1516%E2%80%931517)'),
  ('Q537923', 'Battle of Ridaniya', 'The Battle of Ridaniya or Battle of Ridanieh (Arabic: معركة الريدانية; Turkish: Ridaniye Muharebesi) was fought on January 22, 1517, in Egypt. The Ottoman forces of Selim I defeated the Mamluk forces under Al-Ashraf Tuman bay II. The Turks marched into Cairo, and the severed head of Tuman bay II, Egypt’s last Mamluk Sultan, was hung over an entrance gate in the Al Ghourieh quarter of Cairo.', 1517, 1, 22, NULL, NULL, NULL, 'day', '22 January 1517', 55, 'https://en.wikipedia.org/wiki/Battle_of_Ridaniya'),
  ('Q243979', 'Battle of the Nile', 'The Battle of the Nile (also known as the Battle of Aboukir Bay; French: Bataille d''Aboukir) was fought between the Royal Navy and the French Navy at Aboukir Bay in Egypt between 1 and 3 August 1798. It was the climax of the Mediterranean campaign of 1798, which had started three months earlier after a large French fleet sailed from Toulon to Alexandria carrying an expeditionary force under Napoleon.', 1798, 8, 1, NULL, NULL, NULL, 'day', '1 August 1798', 73, 'https://en.wikipedia.org/wiki/Battle_of_the_Nile'),
  ('Q253684', 'French invasion of Egypt and Syria', 'The French invasion of Egypt and Syria (1798–1801) was a military expedition to Ottoman-held Egypt and Syria led by Napoleon Bonaparte during the French Revolutionary Wars. The campaign aimed to undermine British trade routes, expand French influence, and establish a scientific and administrative presence in Egypt.', 1798, 7, 1, 1801, 9, 2, 'day', '1 July 1798 – 2 September 1801', 73, 'https://en.wikipedia.org/wiki/French_invasion_of_Egypt_and_Syria'),
  ('Q332543', 'Battle of the Pyramids', 'The Battle of the Pyramids (French: Bataille des Pyramides), also known as the Battle of Embabeh (bataille d''Embabech), was fought on 21 July 1798 during the French invasion of Egypt and Syria. Occurring near the village of Embabeh, Ottoman Egypt, the battle was named by Napoleon after the distant Great Pyramid of Giza.', 1798, 7, 21, NULL, NULL, NULL, 'day', '21 July 1798', 72, 'https://en.wikipedia.org/wiki/Battle_of_the_Pyramids'),
  ('Q3458323', 'Revolt of Cairo', 'The Revolt of Cairo was a rebellion that occurred on 21–22 October 1798 by inhabitants of Cairo against the French occupation. It was suppressed by the French Army of the Orient under Napoleon.', 1798, 10, 22, 1798, 10, 22, 'day', '22 October 1798', 48, 'https://en.wikipedia.org/wiki/Revolt_of_Cairo'),
  ('Q778800', 'First Battle of Abukir', 'The Battle of Abukir (also known as the Battle of Aboukir or Battle of Abu Qir) was fought on 25 July 1799 between the French Army of the Orient under Napoleon Bonaparte and an Ottoman army under Mustafa Pasha during the French invasion of Egypt and Syria. It is considered the first pitched battle with this name, as there already had been a naval battle on 1 August 1798, the Battle of the Nile.', 1799, 7, 25, NULL, NULL, NULL, 'day', '25 July 1799', 65, 'https://en.wikipedia.org/wiki/Battle_of_Abukir_(1799)'),
  ('Q2887968', 'Battle of Heliopolis', 'The Battle of Heliopolis was fought between the French Army of the Orient under the command of General Jean-Baptiste Kléber and an Ottoman army at Heliopolis on 20 March 1800. The French were victorious, inflicting over 9,000 casualties on the Ottomans while suffering only 600 killed or wounded.', 1800, 3, 20, NULL, NULL, NULL, 'day', '20 March 1800', 51, 'https://en.wikipedia.org/wiki/Battle_of_Heliopolis_(1800)'),
  ('Q2510511', 'Second Battle of Abukir', 'The Battle of Abukir of 8 March 1801 was the second pitched battle of the French invasion of Egypt and Syria to be fought at Abu Qir on the Mediterranean coast, near the Nile Delta. The landing of the British expeditionary force under Lieutenant-General Sir Ralph Abercromby was intended to defeat or drive out an estimated 21,000 remaining French troops in Egypt.', 1801, 3, 8, NULL, NULL, NULL, 'day', '8 March 1801', 57, 'https://en.wikipedia.org/wiki/Battle_of_Abukir_(1801)'),
  ('Q2750968', 'Battle of Alexandria', 'The Battle of Alexandria (also known as the Battle of Canope/Canopus) was fought on 21 March 1801, where the British army and naval forces repelled an assault by the French army as part of the French invasion of Egypt and Syria. Led by General Sir Ralph Abercromby, the British entrenched army engaged a French force under Divisional-general Jacques-François Menou near the ruins of Nicopolis, on the narrow spit of land between the Mediterranean Sea and Abukir.', 1801, 3, 21, NULL, NULL, NULL, 'day', '21 March 1801', 51, 'https://en.wikipedia.org/wiki/Battle_of_Alexandria_(1801)'),
  ('Q3485805', 'Siege of Alexandria', 'The siege of Alexandria (17 August – 2 September 1801) was fought during the French Revolutionary Wars between French and British forces. It was the last action of the French invasion of Egypt and Syria (1798–1801).', 1801, 8, 17, 1801, 9, 2, 'day', '17 August 1801 – 2 September 1801', 50, 'https://en.wikipedia.org/wiki/Siege_of_Alexandria_(1801)'),
  ('Q616939', 'Anglo-Egyptian War', 'The British conquest of Egypt, also known as the 2nd Anglo-Egyptian War (Arabic: الحرب الإنجليزية المصرية, romanised: al-Ḥarb al-Injlīzīyah al-Miṣrīyah), occurred in 1882 between mostly Egyptian and Sudanese forces under Ahmed ‘Urabi and the United Kingdom. Egypt was a country under growing foreign influence from global powers during the 19th century.', 1882, 7, NULL, 1882, 9, NULL, 'month', 'July 1882 – September 1882', 59, 'https://en.wikipedia.org/wiki/Anglo-Egyptian_War'),
  ('Q1420382', 'Battle of Tel el-Kebir', 'The Battle of Tel El Kebir (often spelled Tel-El-Kebir), fought on 13 September 1882 at Tell El Kebir in Egypt, 110 km north-north-east of Cairo, proved the decisive engagement of the Anglo-Egyptian War of 1882. A British army led by Lieutenant General Sir Garnet Wolseley approached under cover of darkness and defeated an entrenched Egyptian force under the command of Ahmed ʻUrabi in a sudden assault.', 1882, 9, 13, NULL, NULL, NULL, 'day', '13 September 1882', 55, 'https://en.wikipedia.org/wiki/Battle_of_Tell_El_Kebir'),
  ('Q2474428', 'Egypt during British influence', 'The history of Egypt under the British lasted from 1882, when it was occupied by British forces during the Anglo-Egyptian War, until 22 February 1922 when Unilateral Declaration was issued because, according to the official British archives, Egypt became an independent state after the issuance of the Declaration of February 28, 1922, thus ending exactly 40 years of British occupation of Egypt. Despite containing four reservations, the Unilateral Declaration was an important step, as Egypt was the first Arab country to gain official recognition of its independence from European colonialism.', 1882, NULL, NULL, 1954, NULL, NULL, 'year', '1882–1954', 58, 'https://en.wikipedia.org/wiki/History_of_Egypt_under_the_British'),
  ('Q2722527', 'Battle of Romani', 'The Battle of Romani was the last ground attack of the Central Powers on the Suez Canal at the beginning of the Sinai and Palestine campaign during the First World War. The battle was fought between 3 and 5 August 1916 near the Egyptian town of Romani and the site of ancient Pelusium on the Sinai Peninsula, 23 mi (37 km) east of the Suez Canal.', 1916, 8, 3, 1916, 8, 5, 'day', '3 August 1916 – 5 August 1916', 57, 'https://en.wikipedia.org/wiki/Battle_of_Romani'),
  ('Q625798', 'Western Desert campaign', 'The Western Desert campaign (Desert War) took place in the deserts of Egypt and Libya and was the main theatre in the North African campaign of the Second World War. Military operations began in June 1940 with the Italian declaration of war and the Italian invasion of Egypt from Libya in September.', 1940, 6, 11, 1943, 2, 4, 'day', '11 June 1940 – 4 February 1943', 64, 'https://en.wikipedia.org/wiki/Western_Desert_campaign'),
  ('Q698421', 'Italian invasion of Egypt', 'The Italian invasion of Egypt (Operazione E) was an offensive in the Second World War from Italian Libya, against British, Commonwealth and Free French in the neutral Kingdom of Egypt. The invasion by the Italian 10th Army (10ª Armata) ended border skirmishing on the frontier and began the Western Desert Campaign (1940–1943) proper.', 1940, 9, 9, 1940, 9, 16, 'day', '9 September 1940 – 16 September 1940', 66, 'https://en.wikipedia.org/wiki/Italian_invasion_of_Egypt'),
  ('Q2606324', 'Raid on Alexandria', 'The Raid on Alexandria (Operazione EA 3) was carried out on 19 December 1941 by Royal Italian Navy (Regia Marina) divers of the Decima Flottiglia MAS (Decima Flottiglia Motoscafi Armati Siluranti), who attacked and severely damaged two Royal Navy battleships at their moorings and damaged an oil tanker and a destroyer in the harbour of Alexandria, Egypt, using Siluro Lenta Corsa, manned torpedoes. The attacks came at a difficult time for the Mediterranean Fleet, after the loss of the aircraft carrier HMS Ark Royal and the battleship Barham to U-boats, the loss of ships during the Battle of…', 1941, 12, 19, NULL, NULL, NULL, 'day', '19 December 1941', 55, 'https://en.wikipedia.org/wiki/Raid_on_Alexandria_(1941)'),
  ('Q153376', 'Second Battle of El Alamein', 'The Second Battle of El Alamein (23 October – 4 November 1942) was a battle of the Second World War that took place near the Egyptian railway halt of El Alamein. The First Battle of El Alamein and the Battle of Alam el Halfa had prevented the Axis from advancing further into Egypt.', 1942, 10, 23, 1942, 11, 11, 'day', '23 October 1942 – 11 November 1942', 73, 'https://en.wikipedia.org/wiki/Second_Battle_of_El_Alamein'),
  ('Q162250', 'First Battle of El Alamein', 'The First Battle of El Alamein (1–27 July 1942) was a battle of the Western Desert campaign of World War II, fought in Egypt between Axis (German and Italian) forces of the Panzer Army Africa—which included the Afrika Korps under Field Marshal Erwin Rommel—and Allied (British Empire and Commonwealth) forces of the Eighth Army under General Claude Auchinleck. In this battle the British halted a second advance by the Axis forces into Egypt.', 1942, 7, 1, 1942, 7, 27, 'day', '1 July 1942 – 27 July 1942', 72, 'https://en.wikipedia.org/wiki/First_Battle_of_El_Alamein'),
  ('Q541997', 'Battle of Alam el Halfa', 'The Battle of Alam el Halfa took place between 30 August and 5 September 1942 south of El Alamein during the Western Desert Campaign of the Second World War. Panzerarmee Afrika (Generalfeldmarschall Erwin Rommel), attempted an envelopment of the British Eighth Army (Lieutenant-General Bernard Montgomery).', 1942, 8, 30, 1942, 9, 5, 'day', '30 August 1942 – 5 September 1942', 64, 'https://en.wikipedia.org/wiki/Battle_of_Alam_el_Halfa'),
  ('Q22947785', 'Battle of Mersa Matruh', 'The Battle of Mersa Matruh was fought from 26 to 29 June 1942, following the defeat of the Eighth Army (General Sir Claude Auchinleck) at the Battle of Gazala and was part of the Western Desert Campaign of the Second World War. The battle was fought with the German–Italian Panzer Army Afrika (Panzerarmee Afrika (Generalfeldmarschall Erwin Rommel).', 1942, 6, 29, NULL, NULL, NULL, 'day', '29 June 1942', 47, 'https://en.wikipedia.org/wiki/Battle_of_Mersa_Matruh'),
  ('Q4115786', 'TWA Flight 903', 'TWA Flight 903 was a regularly scheduled flight from Bombay International Airport, India to New York-Idlewild Airport, via Cairo-King Farouk Airport and Rome-Ciampino Airport. On 31 August 1950, the flight crashed in Egypt due to engine failure.', 1950, 8, 31, NULL, NULL, NULL, 'day', '31 August 1950', 48, 'https://en.wikipedia.org/wiki/TWA_Flight_903'),
  ('Q4217221', 'Pakistan International Airlines Flight 705', 'Pakistan International Airlines Flight 705 (PK705) was a Boeing 720 airliner that crashed while descending to land at Cairo International Airport on 20 May 1965. Of the 127 passengers and crew on board, all but 6 were killed.', 1965, 5, 20, NULL, NULL, NULL, 'day', '20 May 1965', 47, 'https://en.wikipedia.org/wiki/Pakistan_International_Airlines_Flight_705'),
  ('Q49100', 'Yom Kippur War', 'The Yom Kippur War, also known as the 1973 Arab–Israeli War, the fourth Arab–Israeli War, the October War, or the Ramadan War (6–25 October 1973), was fought between Israel and a coalition of Arab states led by Egypt and Syria. Most of the fighting occurred in the Sinai Peninsula and the Golan Heights, territories occupied by Israel in 1967.', 1973, 10, 6, 1973, 10, 26, 'day', '6 October 1973 – 26 October 1973', 86, 'https://en.wikipedia.org/wiki/Yom_Kippur_War'),
  ('Q1576861', 'Libyan Arab Airlines Flight 114', 'Libyan Arab Airlines Flight 114 was a regularly scheduled international passenger flight from Tripoli, Libya, to Cairo, Egypt, through Benghazi in Libya. The flight was shot down on 21 February 1973 by two Israeli McDonnell Douglas F-4 fighter jets after it mistakenly entered the airspace of Egypt''s Sinai Peninsula – then under Israeli occupation – resulting in the death of 108 passengers and crew, with 5 survivors.', 1973, 2, 21, NULL, NULL, NULL, 'day', '21 February 1973', 57, 'https://en.wikipedia.org/wiki/Libyan_Arab_Airlines_Flight_114'),
  ('Q2072316', 'Battle of the Chinese Farm', 'The Battle of the Chinese Farm took place during October 15 to October 17, 1973 between the Egyptian Army and the Israel Defense Forces (IDF), as part of the Yom Kippur War. It was fought in the Sinai Peninsula, north of the Great Bitter Lake and just east of the Suez Canal, near an Egyptian agricultural research station.', 1973, NULL, NULL, 1973, 10, 17, 'year', '1973', 48, 'https://en.wikipedia.org/wiki/Battle_of_the_Chinese_Farm'),
  ('Q2705872', 'Battle of Baltim', 'The Battle of Baltim (also Battle of Damietta, Battle of Baltim–Damietta, Battle of Damietta–Baltim or Battle of Damietta – El Burelos) was fought between the Israeli Navy and the Egyptian Navy on 8–9 October, 1973, during the Yom Kippur War. It took place off the Nile Delta, between Baltim and Damietta.', 1973, 10, 9, NULL, NULL, NULL, 'day', '9 October 1973', 48, 'https://en.wikipedia.org/wiki/Battle_of_Baltim'),
  ('Q2756743', 'assassination of Anwar Sadat', 'On 6 October 1981, Anwar Sadat, the 3rd president of Egypt, was assassinated during the annual victory parade held in Cairo to celebrate the victory over Israel in the Yom Kippur War. The assassination was undertaken by members of the Egyptian Islamic Jihad.', 1981, 10, 6, NULL, NULL, NULL, 'day', '6 October 1981', 53, 'https://en.wikipedia.org/wiki/Assassination_of_Anwar_Sadat'),
  ('Q53600', 'Luxor massacre', 'The Luxor massacre was a terrorist attack that occurred on 17 November 1997 in Egypt. It was perpetrated by al-Jama''a al-Islamiyya and resulted in the deaths of 62 people, most of whom were tourists.', 1997, 11, 17, NULL, NULL, NULL, 'day', '17 November 1997', 59, 'https://en.wikipedia.org/wiki/Luxor_massacre'),
  ('Q1427211', 'Flash Airlines Flight 604', 'Flash Airlines Flight 604 was a charter flight from Sharm El Sheikh International Airport in Egypt to Charles de Gaulle International Airport in Paris, France, with a stop-over at Cairo International Airport, provided by Egyptian private charter company Flash Airlines. On 3 January 2004, the Boeing 737-300 that was operating the route crashed into the Red Sea shortly after takeoff from Sharm El Sheikh, killing all 135 passengers, most of whom were French tourists, and all thirteen crew members.', 2004, 1, 3, NULL, NULL, NULL, 'day', '3 January 2004', 60, 'https://en.wikipedia.org/wiki/Flash_Airlines_Flight_604'),
  ('Q29198', '2011 Egyptian revolution', 'The 2011 Egyptian revolution, also known as the 25 January Revolution (Arabic: ثورة ٢٥ يناير, romanized: Thawrat khamsa wa-ʿišrūn yanāyir), began on 25 January 2011 and spread across Egypt. The date was set by various youth groups to coincide with National Police Day as a statement against increasing police brutality during the later years of Hosni Mubarak''s presidency.', 2011, 1, 25, 2011, 2, 11, 'day', '25 January 2011 – 11 February 2011', 81, 'https://en.wikipedia.org/wiki/2011_Egyptian_revolution'),
  ('Q685746', 'Port Said Stadium riot', 'The Port Said Stadium riot was a riot which occurred at Port Said Stadium in Port Said, Egypt on 1 February, 2012, following an Egyptian Premier League football match between Al Masry and Al Ahly. Seventy-four people were killed and more than 500 injured after thousands of Al Masry fans invaded the pitch following a 3–1 victory of their club.', 2012, 2, 1, NULL, NULL, NULL, 'day', '1 February 2012', 67, 'https://en.wikipedia.org/wiki/Port_Said_Stadium_riot'),
  ('Q3720660', '2012–2013 Egyptian protests', 'The 2012–2013 Egyptian protests (sometimes called the Hirak Uprising) were part of the crisis in Egypt including the June 2013 protests, the July 2013 coup d''état, and part of the post-coup unrest. They saw varying opposition against three contiguous heads of state; namely, the Supreme Council of the Armed Forces (SCAF), Muslim Brotherhood, and the de facto ruling Egyptian Armed Forces.', 2012, 11, 22, 2013, 7, 3, 'day', '22 November 2012 – 3 July 2013', 56, 'https://en.wikipedia.org/wiki/2012%E2%80%932013_Egyptian_protests'),
  ('Q5381891', '2013 Luxor hot air balloon crash', 'On 26 February 2013, a hot air balloon crashed near Luxor, Egypt, killing 19 out of the 21 people on board. A fire developed in the basket due to a leak in the balloon''s gas fuel system, causing the balloon to deflate mid-air and crash to the ground.', 2013, 2, 26, NULL, NULL, NULL, 'day', '26 February 2013', 53, 'https://en.wikipedia.org/wiki/2013_Luxor_hot_air_balloon_crash'),
  ('Q13605743', '2013 Egyptian coup d''état', 'On July 3, 2013, then-President of Egypt Mohamed Morsi was overthrown by a coup d''etat led by Egyptian army chief General Abdel Fattah el-Sisi, who led a coalition to remove Morsi from power and suspend the Egyptian constitution of 2012. The move came after an ultimatum that the government "resolve its differences" with protesters during widespread national protests.', 2013, 7, 3, NULL, NULL, NULL, 'day', '3 July 2013', 69, 'https://en.wikipedia.org/wiki/2013_Egyptian_coup_d''%C3%A9tat'),
  ('Q14575581', 'August 2013 Rabaa massacre', 'On 14 August 2013, the Egyptian police and to a lesser extent the armed forces, under the command of then-Defense Minister Abdel Fattah el-Sisi, used lethal force to clear two camps of protesters in Cairo. Estimates of those killed vary from 600 to 2,600.', 2013, 8, 14, NULL, NULL, NULL, 'day', '14 August 2013', 56, 'https://en.wikipedia.org/wiki/Rabaa_massacre'),
  ('Q21282782', 'Metrojet Flight 9268', 'Metrojet Flight 9268 was an international chartered passenger flight operated by Russian airline Kogalymavia (branded as Metrojet). On 31 October 2015, at 06:13 EST (04:13 UTC), the Airbus A321 operating the flight exploded above the northern Sinai Peninsula following its departure from Sharm El Sheikh International Airport, Egypt, en route to Pulkovo Airport, Saint Petersburg, Russia.', 2015, 10, 31, NULL, NULL, NULL, 'day', '31 October 2015', 77, 'https://en.wikipedia.org/wiki/Metrojet_Flight_9268'),
  ('Q24091473', 'EgyptAir Flight 804', 'EgyptAir Flight 804 was a regularly scheduled international passenger flight from Paris Charles de Gaulle Airport to Cairo International Airport, operated by EgyptAir. On 19 May 2016 at 02:33 Egypt Standard Time (UTC+2), the Airbus A320 crashed into the Mediterranean Sea, killing all 66 occupants on board.', 2016, 5, 19, NULL, NULL, NULL, 'day', '19 May 2016', 73, 'https://en.wikipedia.org/wiki/EgyptAir_Flight_804'),
  ('Q30060577', '2017 Minya bus attack', 'On 26 May 2017, masked gunmen opened fire on a convoy carrying Copts from Maghagha in Egypt''s Minya Governorate to the Monastery of Saint Samuel the Confessor, killing at least 33 people and injuring 22 others.', 2017, 5, 26, NULL, NULL, NULL, 'day', '26 May 2017', 53, 'https://en.wikipedia.org/wiki/2017_Minya_bus_attack'),
  ('Q43544477', '2017 Sinai mosque attack', 'At 1:50 PM EET on 24 November 2017, the al-Rawda mosque was attacked by roughly 40 ISIL gunmen during Friday prayers. The mosque is located in the village of Al-Rawda east of the town of Bir al-Abed in Egypt''s North Sinai Governorate.', 2017, 11, 24, NULL, NULL, NULL, 'day', '24 November 2017', 67, 'https://en.wikipedia.org/wiki/2017_Sinai_mosque_attack'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q122311648', 'Storm Daniel', 'Storm Daniel, also known as Medicane Daniel or Cyclone Daniel, was a relatively weak yet catastrophic and erratic tropical cyclone that became the deadliest Mediterranean tropical-like cyclone in recorded history, as well as the second-costliest tropical cyclone on record outside of the North Atlantic Basin (after Typhoon Doksuri). Forming as a low-pressure system around 4 September 2023, the storm affected Greece, Bulgaria, and Turkey with extensive flooding.', 2023, 9, NULL, 2023, 9, 13, 'month', 'September 2023 – 13 September 2023', 72, 'https://en.wikipedia.org/wiki/Storm_Daniel');
